-- fix_online_20260927.sql  支付方式功能开关 + 装修订单路径修复
-- 依据：本地库逐行 diff（form 68/135 仅差新字段；config 缺两行；eb_theme 存在 pages/goods/order_list 错误分包路径）
-- 范围：eb_system_form_temp(68,135) / eb_system_config(2行) / eb_theme(四列 REPLACE)
-- 禁止：并入 02_patches_all.sql 整包执行

-- 1) eb_theme 错误分包路径修复（pages/goods/order_list -> pages/users/order_list）
UPDATE eb_theme SET
  home_data     = REPLACE(home_data,     'pages/goods/order_list', 'pages/users/order_list'),
  category_data = REPLACE(category_data, 'pages/goods/order_list', 'pages/users/order_list'),
  detail_data   = REPLACE(detail_data,   'pages/goods/order_list', 'pages/users/order_list'),
  user_data     = REPLACE(user_data,     'pages/goods/order_list', 'pages/users/order_list');

